mapper.select:
select ues.id,u.id as userId ,e.title, u.real_name, ues.user_time, ues.user_score, ues.limit_time, ues.count,e.id as examId from t_user_exams_score as ues join t_user as u on ues.user_id = u.id join t_exam as e on ues.exam_id = e.id join t_exam_subject as ug on e.id = ug.exam_id
ug.subject_id = #{subjectId} and ues.exam_id = #{examId}
and u.real_name like concat('%',#{realName},'%')

select u.real_name, g.subject_name, ues.user_score as score
from t_user_exams_score as ues
join t_user as u on ues.user_id = u.id
join t_exam_subject as ug on ues.exam_id = ug.exam_id
join t_subject as g on ug.subject_id = g.id
where ues.exam_id = #{examId}
and g.id = #{subjectId}
order by ues.user_score desc;
